<script setup lang="ts">
import {trackProductEvent} from "../analytics/product-events"
import ModelControlButton from '../play-controls/ModelControlButton.vue'
import PlaySettings from '../play-controls/PlaySettings.vue'
import TaskProgress from '../experience/TaskProgress.vue'
import ScriptProgress from './ScriptProgress.vue'
import PromptSelector from '../workspace/PromptSelector.vue'
import EvidenceSearch from '../foundation/EvidenceSearch.vue'
import WorldScene from './WorldScene.vue'
import WorldPortraitScene from './WorldPortraitScene.vue'
import SceneReply from './SceneReply.vue'
import WorldAppearanceProvider from '../components/WorldAppearanceProvider.vue'
import CharacterAvatar from '../components/CharacterAvatar.vue'
import {sceneDialogueSegments,streamStoryText} from './scene-dialogue'
import PublicStreamText from '../components/PublicStreamText.vue'
import {ref,computed,onMounted,onUnmounted,watch,nextTick} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {ArrowLeft,GitBranch,BookOpen,Users,Sparkles,ArrowUp,Square,MoreHorizontal,RotateCcw,CornerUpLeft,ArrowUpRight,SlidersHorizontal,Save,Feather,Compass,MapPin,Clock3} from 'lucide-vue-next'
import Sheet from '../components/Sheet.vue'
import StoryImages from '../components/StoryImages.vue'
import WorldDetails from './WorldDetails.vue'
import WorldWritePanel from './WorldWritePanel.vue'
import WorldCorrection from './WorldCorrection.vue'
import {targetDraft} from './target-draft'
import {interpretInput} from './action-intent'
import {useWorld} from './store'
import {worldApi} from './api'
import {worldMutation,clearWorldMutation,clearConfirmedWorldMutation} from './mutation-intent'
import {authGeneration,ApiError} from '../api'
import {rememberContext,worldContext} from '../api/stories'
import {useApp} from '../stores/app'
import type {WorldCheckpoint,WorldLine,ActionKind,WorldEntity} from './types'
import type {Anchor} from '../api/types'
import {useRequestScope} from '../platform/request-scope'
const route=useRoute(),router=useRouter(),store=useWorld(),app=useApp(),capture=useRequestScope(),sheet=ref(''),sceneCount=ref(6),viewport=ref<HTMLElement|null>(null),following=ref(true),kind=ref<ActionKind>('action'),selected=ref<WorldCheckpoint|null>(null),selectedDraft=ref(''),lineName=ref(''),error=ref(''),busy=ref(false),correctionValue=ref(''),forkName=ref(''),customName=ref(''),customIdentity=ref(''),characterId=ref('')
const ready=ref(false),sceneMode=computed(()=>(route.path||route.fullPath.split('?')[0]).endsWith('/explore'))
const portraitMode=computed(()=>sceneMode.value&&store.world?.portraitDialogue===true)
function setMode(value:boolean){const query={...route.query};delete query.presentation;void router.push({path:`/worlds/${route.params.worldId}/${value?'explore':'play'}`,query})}
function useFixed(action:{message:string;kind:ActionKind}){if(store.running||store.busy)return;store.input=action.message;kind.value=action.kind;document.querySelector<HTMLTextAreaElement>('.world-compose textarea')?.focus()}
function sendStory(){void store.act(store.input,interpretInput(store.input,kind.value==='dialogue'?'character':undefined))}
const renameBusy=ref(false),renameError=ref(''),renameStale=ref(false),renameRefreshed=ref(false)
const returnStory=ref(''),returnLink=computed(()=>'/stories/'+(returnStory.value||'world-'+String(route.params.worldId)))
function viewLink(view:'play'|'read'|'lines',lineId=store.line?.id||''){const pathView=view==='play'&&sceneMode.value?'explore':view;return returnStory.value?{path:`/worlds/${route.params.worldId}/${pathView}`,query:{line:lineId,story:returnStory.value}}:`/worlds/${route.params.worldId}/${pathView}?line=${lineId}`}
const canBranch=computed(()=>store.world?.status==='active')
const liveStory=computed(()=>streamStoryText(store.task?.stream.text||'',store.state?.entities.filter(e=>e.type==='character')||[]))
const opening=computed(()=>store.history.find(cp=>cp.id===store.line?.headCheckpointId&&cp.kind==='start'&&cp.text))
const scenes=computed(()=>store.history.filter((c,index,history)=>c.text&&c.kind!=='start'&&c.kind!=='scene_move'&&!(c.kind==='correction'&&c.text===history[index-1]?.text)).slice(-sceneCount.value)),head=computed(()=>store.line?.head),state=computed(()=>selected.value?.state||store.state),phase=computed(()=>store.recovering?'正在恢复保存…':({queued:'故事正在等待…',preparing_world:'正在整理故事…',directing:'故事正在回应…',writing:'文字正在展开…',saving:'正在保存…',checking:'正在核对本轮结果…'} as Record<string,string>)[store.task?.phase||'']||'故事正在回应…')
let previousTop=0,viewVersion=0
function openSheet(name:string){viewVersion++;sheet.value=name;renameBusy.value=false;renameError.value='';renameStale.value=false;renameRefreshed.value=false}
const modelSettings=ref<InstanceType<typeof PlaySettings>>(),modelButton=ref<InstanceType<typeof ModelControlButton>>()
async function closeSettings(){if(await modelSettings.value?.requestClose())closeSheet()}
function closeSheet(){openSheet('');selected.value=null}
function scroll(){const v=viewport.value;if(!v)return;if(v.scrollTop<previousTop-3)following.value=false;else if(v.scrollHeight-v.clientHeight-v.scrollTop<70)following.value=true;previousTop=v.scrollTop}
async function follow(){await nextTick();if(following.value&&viewport.value)viewport.value.scrollTop=viewport.value.scrollHeight}
watch(()=>store.task?.stream.text,follow);watch(()=>store.line?.headCheckpointId,follow)
watch(()=>store.input,()=>void store.saveInput())
let resumeGeneration=0
async function rememberPlay(){
  const scope=capture(),generation=++resumeGeneration,world=store.world,line=store.line,head=store.line?.head
  if(!world||!line||!head?.state?.playerId||world.status!=='active'||line.status!=='active')return
  const valid=()=>scope.valid()&&generation===resumeGeneration&&store.world?.id===world.id&&store.line?.id===line.id&&store.line?.headCheckpointId===head.id
  const context=worldContext(world,line.id,head.id,head.state.playerId)
  try{await rememberContext(context,valid)}catch{/* Resume CAS never overrides another device or changes the actionable head. */}
}
async function load(){ready.value=false;closeSheet();returnStory.value='';const scope=capture();await store.load(String(route.params.worldId),String(route.query.line||''));if(!scope.valid())return;ready.value=true;if(store.line)trackProductEvent('play.enter',{worldId:store.world?.id,lineId:store.line.id,mode:sceneMode.value?'360':'text'});lineName.value=store.line?.name||'';await follow();void rememberPlay()
  const origin=String(route.query.story||''),world=store.world,line=store.line,head=store.line?.head
  if(/^(book|world)-[a-f0-9]{32}$/.test(origin)&&world&&line&&head?.state?.playerId){try{await import('../api').then(({api})=>api('/stories/'+origin+'/context/validate',{method:'POST',body:{...worldContext(world,line.id,head.id,head.state!.playerId),storyId:origin}}));if(scope.valid())returnStory.value=origin}catch{/* Invalid origin never selects a different story's return target. */}}
}
watch(()=>store.line?.headCheckpointId,()=>void nextTick().then(rememberPlay))
async function view(cp:WorldCheckpoint){const version=++viewVersion,scope=capture(),worldId=store.world?.id,lineId=store.line?.id;if(!worldId)return;const valid=()=>scope.valid()&&version===viewVersion&&worldId===store.world?.id&&lineId===store.line?.id;error.value='';try{const value=await worldApi<WorldCheckpoint>('/worlds/'+worldId+'/checkpoints/'+cp.id,{cache:true});if(valid()){selected.value=value;openSheet('scene')}}catch(e){if(valid())error.value=(e as Error).message}}
async function fork(mode:string,cp=selected.value||head.value){if(busy.value||!store.world||!cp)return;const scope=capture();busy.value=true;try{const slot='fork:'+store.world.id;await clearConfirmedWorldMutation(slot,scope.valid);if(!scope.valid())return;const result=await worldMutation<WorldLine>(slot,'/worlds/'+store.world.id+'/fork',{checkpointId:cp.id,mode,name:forkName.value||({rechoose:'另一种选择',restart:'重新开始',identity:'另一个人的故事'} as Record<string,string>)[mode]||'我的存档',characterId:characterId.value||null,customName:customName.value,customIdentity:customIdentity.value},scope.valid);if(!scope.valid())return;await clearWorldMutation(slot,scope.valid);if(!scope.valid())return;closeSheet();busy.value=false;await router.push(viewLink('play',result.id))}catch(e){if(scope.valid())error.value=(e as Error).message}finally{if(scope.valid())busy.value=false}}
async function rewrite(){if(busy.value||!selected.value||!store.world)return;const scope=capture();busy.value=true;try{const slot='rewrite:'+store.world.id;await clearConfirmedWorldMutation(slot,scope.valid);if(!scope.valid())return;const result=await worldMutation<{lineId:string}>(slot,'/worlds/'+store.world.id+'/rewrite',{checkpointId:selected.value.id,instruction:correctionValue.value},scope.valid);if(!scope.valid())return;await clearWorldMutation(slot,scope.valid);if(!scope.valid())return;closeSheet();busy.value=false;await router.push(viewLink('play',result.lineId))}catch(e){if(scope.valid())error.value=(e as Error).message}finally{if(scope.valid())busy.value=false}}
async function publish(){if(!store.world||!head.value)return;const scope=capture();busy.value=true;try{const result=await worldApi<{bookId:string;branchId:string;revisionId:string;readingAnchor:Anchor}>('/worlds/'+store.world.id+'/checkpoints/'+head.value.id+'/publish',{method:'POST',key:'publish:'+head.value.id,body:{}});if(scope.valid())await router.push({path:`/books/${result.bookId}/read`,query:{branch:result.branchId,revision:result.revisionId,chapter:result.readingAnchor.chapterId,anchor:JSON.stringify(result.readingAnchor),story:returnStory.value||'world-'+store.world.id}})}catch(e){if(scope.valid())error.value=(e as Error).message}finally{if(scope.valid())busy.value=false}}
function renameScope(){const scope=capture(),version=viewVersion,worldId=store.world?.id,lineId=store.line?.id;return{worldId,lineId,valid:()=>scope.valid()&&version===viewVersion&&sheet.value==='menu'&&worldId===store.world?.id&&lineId===store.line?.id}}
async function refreshRename(){
  const request=renameScope();if(!request.worldId||!request.lineId||busy.value||renameBusy.value||!renameStale.value)return
  renameBusy.value=true
  try{const fresh=await worldApi<WorldLine>('/worlds/'+request.worldId+'/lines/'+request.lineId);if(request.valid()&&store.line){store.line={...store.line,name:fresh.name,version:fresh.version,status:fresh.status};renameError.value='';renameStale.value=false;renameRefreshed.value=true}}
  catch(e){if(request.valid())renameError.value=(e as Error).message}finally{if(request.valid())renameBusy.value=false}
}
async function rename(){
  const request=renameScope();if(!request.worldId||!request.lineId||!store.line||busy.value||renameBusy.value||renameStale.value)return
  renameBusy.value=true;renameError.value=''
  try{await worldApi('/worlds/'+request.worldId+'/lines/'+request.lineId,{method:'PATCH',body:{expectedVersion:store.line.version,name:lineName.value}});if(!request.valid())return;await store.reloadHead();if(request.valid())closeSheet()}
  catch(e){if(request.valid()){renameError.value=(e as Error).message;renameStale.value=e instanceof ApiError&&e.code==='VERSION_CONFLICT'}}finally{if(request.valid())renameBusy.value=false}
}
function correct(){selected.value=null;openSheet('correct')}
async function corrected(lineId:string){closeSheet();await router.push(viewLink('play',lineId))}
async function talkTo(entity:WorldEntity){
  if(store.running||store.busy||head.value?.state?.ended||store.line?.status!=='active'||store.world?.status!=='active')return
  store.input=targetDraft(store.input,entity,store.state?.entities||[]);kind.value=entity.nearby?'dialogue':'action';closeSheet()
  await nextTick();document.querySelector<HTMLTextAreaElement>('.world-compose textarea')?.focus()
}
function awaitRescue(){kind.value='wait';store.input=store.input||'我等待可能到来的救援。';document.querySelector<HTMLTextAreaElement>('.world-compose textarea')?.focus()}
function key(event:KeyboardEvent){if(event.key==='Enter'&&(event.ctrlKey||event.metaKey)){event.preventDefault();sendStory()}}
function resume(){if(app.online&&store.line?.pendingTaskId&&!store.running)void store.watchTask(store.line.pendingTaskId)}
watch(()=>[route.params.worldId,route.query.line,route.query.story,route.path],load)
function removedSource(event:Event){const id=(event as CustomEvent<{bookId:string}>).detail?.bookId;if(store.world?.sourceBookId===id){store.world.sourceRemoved=true;if(returnStory.value==='book-'+id)returnStory.value='world-'+store.world.id}}
onMounted(()=>{void load();window.addEventListener('reader-resume',resume);window.addEventListener('reader-book-deleted',removedSource)});onUnmounted(()=>{viewVersion++;void store.saveInput();store.stopWatching();window.removeEventListener('reader-resume',resume);window.removeEventListener('reader-book-deleted',removedSource)})
</script>
<template><WorldAppearanceProvider :world-id="store.world?.id" :line-id="store.line?.id"><div class="world-play" :data-line-id="store.line?.id"><header class="world-play-header"><RouterLink :to="returnLink" class="icon-button" aria-label="返回故事入口"><ArrowLeft :size="21"/></RouterLink><div class="world-play-title"><strong>{{store.world?.name||'互动世界'}}</strong><small>{{store.line?.name||'你的故事'}}<span v-if="store.world?.sourceRemoved"> · 来源已移除</span></small></div><div v-if="!store.world?.authorTrial" class="world-scene-mode-toggle" aria-label="游玩模式"><button :class="{active:sceneMode}" @click="setMode(true)">360° 世界</button><button :class="{active:!sceneMode}" @click="setMode(false)">纯故事</button></div><button v-if="store.state?.plot" class="world-script-progress-link" @click="openSheet('plot')">{{store.state.plot.ending?.phase==='resolved'?'善后已完成':store.state.plot.ending?store.state.plot.ending.phase==='legacy_unverified'||!store.state.plot.ending.phase?'旧版结局待核验':'结局善后 '+(store.state.plot.resolution?.completedCount||0)+' / '+(store.state.plot.resolution?.totalCount||0):'任务 '+store.state.plot.completedCount+' / '+store.state.plot.totalCount}}</button><ModelControlButton v-if="store.line" ref="modelButton" kind="lines" :identity="store.line.id" @open="openSheet('model-memory')"/><nav aria-label="世界视图"><span class="active">游玩</span><RouterLink :to="viewLink('read')"><BookOpen :size="17"/>阅读</RouterLink><RouterLink :to="viewLink('lines')"><GitBranch :size="17"/>世界线</RouterLink></nav><button class="icon-button world-mobile-details" aria-label="打开世界资料" @click="selected=null;openSheet('details')"><Users :size="20"/></button><button class="icon-button" aria-label="世界操作" @click="selected=null;openSheet('menu')"><MoreHorizontal :size="22"/></button></header><p v-if="store.world?.authorTrial" class="product-hint" role="status">作者文字试玩 · 配置 {{store.world.authorTrial.authorVersion}} · 已预留 {{store.world.authorTrial.reserved.generations}} / {{store.world.authorTrial.limits.generations}} 次。原主线保持原状。</p><div v-if="!ready" class="loading">正在进入世界…</div><div v-else-if="!store.line" class="empty"><p v-if="store.error" class="error" role="alert">{{store.error}}</p><RouterLink v-if="store.world" :to="'/worlds/new?world='+store.world.id" class="world-primary-link">选择一个身份</RouterLink></div><WorldPortraitScene v-else-if="sceneMode&&portraitMode" :key="store.world?.id+':'+store.line?.id" @text="setMode(false)" @details="selected=null;openSheet('details')"/><WorldScene v-else-if="sceneMode" @text="setMode(false)" @details="selected=null;openSheet('details')" @draft="id=>{selectedDraft=id;openSheet(store.drafts.find(d=>d.id===id)?.chapters.length?'write':'draft')}" @history="setMode(false)"/><div v-else class="world-play-layout"><section class="world-story-column"><div v-if="store.state" class="world-presence-bar" aria-label="当前人物、地点和时间"><span><span>{{store.state.entities.find(e=>e.id===store.state?.playerId)?.name}}</span></span><span><MapPin :size="13"/><span>{{store.state.entities.find(e=>e.id===store.state?.location)?.name}}</span></span><span><Clock3 :size="13"/><span>{{store.state.timeLabel}}</span></span></div><div class="world-story-pane"><div ref="viewport" class="world-story-scroll" @scroll="scroll"><div class="world-story-inner"><div v-if="error||store.error" class="error" role="alert">{{error||store.error}}<button v-if="store.retryMessage" :disabled="store.running||store.busy" @click="store.restoreAction">重新填写上次行动</button></div><button v-if="store.history.filter(c=>c.text).length>sceneCount" class="world-earlier" @click="sceneCount+=8">查看更早的故事</button><article v-if="opening&&!scenes.length" class="world-scene world-opening" aria-label="故事开场"><div class="world-scene-heading"><h2>{{opening.title||'故事开场'}}</h2></div><div class="world-prose"><SceneReply :segments="sceneDialogueSegments(opening.text,opening.state?.entities||store.state?.entities||[])"/></div><p class="world-opening-hint">观察身边的人物与物品，或在下方写下你的行动。</p></article><div v-else-if="!scenes.length&&!store.running" class="world-scene-empty"><Compass/><p>故事正等你迈出第一步。</p></div><article v-for="cp in scenes" :key="cp.id" class="world-scene"><div v-if="cp.action" class="world-player-action"><CharacterAvatar :entity-id="cp.state?.playerId||store.state?.playerId" name="你" :size="28"/><span>你</span>{{cp.action}}</div><div class="world-scene-heading"><h2>{{cp.title}}</h2><button class="icon-button" :aria-label="'查看'+cp.title+'的历史操作'" @click="view(cp)"><MoreHorizontal :size="18"/></button></div><div class="world-prose"><SceneReply :segments="sceneDialogueSegments(cp.text,cp.state?.entities||store.state?.entities||[])"/></div></article><article v-if="store.running" class="world-scene world-live-scene"><div class="world-writing-status" role="status"><span class="world-pulse"></span>{{phase}}<span v-if="store.task?.result.chapterCount&&store.task.result.chapterCount>1">{{store.task.result.chapterIndex||1}} / {{store.task.result.chapterCount}}</span></div><TaskProgress :progress="store.task?.progress"/><div v-if="store.task?.stream.text" class="world-prose"><SceneReply :segments="sceneDialogueSegments(store.task.stream.text,store.state?.entities||[],undefined,true)" :stream="{contentId:store.task.stream.contentId||store.task.id,version:store.task.stream.streamVersion||1}" @rendered="follow"/><span class="world-caret"></span></div></article><div v-if="store.drafts.length&&!store.running" class="world-drafts"><button v-for="d in store.drafts" :key="d.id" @click="selectedDraft=d.id;openSheet(d.chapters.length?'write':'draft')"><Feather :size="17"/>{{d.status==='historical'?'查看恢复的正文':d.chapters.length?'查看这次写作 · '+d.chapters.length+' 章':'查看保留的草稿'}}<ArrowUpRight :size="17"/></button></div><div v-if="head&&!store.running&&store.line.status==='active'&&store.world?.status==='active'" class="world-options"><template v-if="!head.state?.ended"><button v-for="(option,i) in head.options" :key="option.text" :disabled="store.busy||!app.online" @click="store.act(option.text,option.kind)"><span>{{String(i+1).padStart(2,'0')}}</span>{{option.text}}<ArrowUpRight :size="17"/></button></template><button v-else :disabled="busy||store.busy||store.running" @click="fork('restart',head)"><RotateCcw :size="18"/>从起点再来一次</button></div></div></div><button v-if="!following" class="world-follow-button" @click="following=true;follow()">回到最新文字 ↓</button></div><form v-if="store.line.status==='active'&&store.world?.status==='active'" class="world-compose" @submit.prevent="sendStory"><div v-if="head?.state?.fixedActions?.length" class="world-fixed-actions"><button v-for="action in head.state.fixedActions" :key="action.id" type="button" :disabled="store.running||store.busy||!app.online" @click="useFixed(action)">{{action.label}}</button><small>选择后确认输入，再发送行动。</small></div><div class="world-compose-tools"><button type="button" :disabled="store.running||store.busy||!app.online||head?.state?.ended" @click="selectedDraft='';openSheet('write')"><Sparkles :size="16"/>写几章</button></div><div v-if="store.state?.entities.find(e=>e.id===store.state?.playerId)?.state?.alive===false&&!head?.state?.ended" class="world-death-options"><span>{{store.state?.rules.deathPolicy==='rescue'?'等待救援':'重生需要付出代价'}}</span><button v-if="store.state?.rules.deathPolicy==='rescue'" type="button" :disabled="store.running||store.busy||!app.online" @click="awaitRescue">等待救援</button></div><div class="world-compose-input"><textarea v-model="store.input" :disabled="head?.state?.ended" maxlength="5000" placeholder="写下接下来想发生的事，或想说的话…" aria-label="你的下一步行动" @keydown="key"></textarea><button v-if="store.running" class="world-send" type="button" aria-label="停止这一轮" @click="store.cancel"><Square :size="20"/></button><button v-else class="world-send" :disabled="!store.input.trim()||store.busy||!app.online||head?.state?.ended" aria-label="提交行动"><ArrowUp :size="22"/></button></div><small v-if="!app.online||!store.connected" class="world-connection-state">{{!app.online?'离线 · 正文仍可阅读，输入已保留':'正在重新连接这次请求…'}}</small></form><div v-else class="world-archived-note">已归档 · 可以阅读这条世界线</div></section><aside v-if="store.state&&head" class="world-state-column" aria-label="世界资料"><WorldDetails :line-id="store.line?.id" :world-id="String(route.params.worldId)" :checkpoint-id="head.id" :state="store.state" :changes="head.changes" :interactive="!store.running&&!store.busy&&app.online&&store.line?.status==='active'&&store.world?.status==='active'" @talk="talkTo" @correct="correct"/></aside></div><Sheet v-if="sheet==='model-memory'&&store.line" title="模型与记忆" @close="closeSettings"><PlaySettings ref="modelSettings" @saved="modelButton?.refresh()" kind="lines" :identity="store.line.id"/></Sheet><Sheet v-if="sheet==='prompts'&&store.world" title="游玩提示词" @close="closeSheet"><PromptSelector :world-id="store.world.id"/></Sheet><Sheet v-if="sheet==='plot'&&store.state?.plot" title="故事进展" @close="closeSheet"><ScriptProgress :progress="store.state.plot"/></Sheet><Sheet v-if="sheet==='details'&&state&&head" title="世界资料" @close="closeSheet"><WorldDetails :line-id="store.line?.id" :world-id="String(route.params.worldId)" :checkpoint-id="selected?.id||head.id" :state="state" :changes="selected?.changes||head.changes" :interactive="!selected&&!store.running&&!store.busy&&app.online&&store.line?.status==='active'&&store.world?.status==='active'" @talk="talkTo" @correct="correct"/></Sheet><Sheet v-if="sheet==='write'" title="让故事继续几章" @close="closeSheet"><WorldWritePanel :turn-id="selectedDraft||undefined" @accepted="closeSheet();following=true;follow()"/></Sheet><Sheet v-if="sheet==='draft'" title="保留的草稿" @close="closeSheet"><div class="scene-draft-transcript"><SceneReply :segments="store.drafts.find(d=>d.id===selectedDraft)?.draftSegments||sceneDialogueSegments(store.drafts.find(d=>d.id===selectedDraft)?.draftText||'',store.state?.entities.filter(e=>e.type==='character'&&e.nearby)||[])"/></div><p class="hint">{{store.drafts.find(d=>d.id===selectedDraft)?.status==='historical'?'从备份恢复 · 已收到的正文片段':'草稿没有改变世界状态。'}}</p></Sheet><Sheet v-if="sheet==='evidence'&&store.world&&store.line" title="已知线索" @close="closeSheet"><EvidenceSearch :world-id="store.world.id" :line-id="store.line.id" :checkpoint-id="head?.id"/></Sheet><Sheet v-if="sheet==='menu'" title="这条世界线" @close="closeSheet"><p v-if="renameError" class="error" role="alert">{{renameError}}</p><button v-if="renameStale" :disabled="busy||renameBusy" @click="refreshRename">载入最新信息</button><small v-if="renameRefreshed" role="status">最新名称：{{store.line?.name}} · {{store.line?.status==='archived'?'已归档':'未归档'}}</small><label>名称<input v-model="lineName" maxlength="120"></label><button :disabled="busy||renameBusy||renameStale||!lineName.trim()" @click="rename">保存名称</button><div class="stack divider"><button :disabled="busy||store.running" @click="openSheet('prompts')">启用私人提示词</button><button :disabled="busy||store.running" @click="openSheet('evidence')">寻找已知线索</button><button :disabled="busy||store.running||!canBranch" @click="openSheet('save');forkName=store.line?.name+' · 存档'"><Save :size="18"/>存一个节点</button><button :disabled="busy||store.running||!canBranch" @click="openSheet('identity')">换一个身份另开线</button><button :disabled="busy||store.running" @click="publish"><BookOpen :size="18"/>存为阅读故事线</button><button :disabled="!canBranch" @click="correct"><SlidersHorizontal :size="18"/>调整世界资料</button><RouterLink v-if="store.world?.sourceBookId&&store.world.sourceAnchor&&!store.world.sourceRemoved" :to="`/books/${store.world.sourceBookId}/read?branch=${store.world.sourceAnchor.branchId}`" class="inline-link">回到来源小说</RouterLink></div></Sheet><Sheet v-if="sheet==='save'" title="给这一刻起个名字" @close="closeSheet"><label>存档名称<input v-model="forkName" maxlength="120"></label><button class="primary" :disabled="busy||!forkName.trim()" @click="fork('continue',head)">保存节点</button></Sheet><Sheet v-if="sheet==='identity'&&store.state" title="另一个人的故事" @close="closeSheet"><label>选择人物<select v-model="characterId"><option value="">创建新人物</option><option v-for="e in store.state.entities.filter(e=>e.type==='character'&&e.state?.alive!==false)" :key="e.id" :value="e.id">{{e.name}}</option></select></label><template v-if="!characterId"><label>名字<input v-model="customName" maxlength="80"></label><label>身份<textarea v-model="customIdentity" maxlength="800"></textarea></label></template><button class="primary" :disabled="busy||!characterId&&(!customName.trim()||!customIdentity.trim())" @click="fork('identity',head)">以这个身份另开世界线</button></Sheet><Sheet v-if="sheet==='scene'&&selected" :title="selected.title" @close="closeSheet"><small>{{selected.state?.timeLabel}} · 回合 {{selected.sequence}}</small><div class="world-prose">{{selected.text}}</div><div class="stack divider"><button :disabled="busy||store.running||!canBranch" @click="fork('rechoose')"><CornerUpLeft :size="18"/>改选这一步</button><button :disabled="busy||store.running||!canBranch" @click="fork('continue')"><GitBranch :size="18"/>从这里继续</button><button :disabled="busy||store.running||!canBranch" @click="openSheet('rewrite');correctionValue=''"><Feather :size="18"/>改写这段正文</button><button @click="openSheet('details')">查看这一刻的世界</button></div><p v-if="error" class="error">{{error}}</p></Sheet><Sheet v-if="sheet==='rewrite'" title="另一种文字表达" @close="closeSheet"><label>你想怎样改写？<textarea v-model="correctionValue" maxlength="1500" placeholder="选填"></textarea></label><button class="primary" :disabled="busy" @click="rewrite">改写，保留本次结果</button></Sheet><Sheet v-if="sheet==='correct'&&store.state&&head" title="调整世界资料" @close="closeSheet"><WorldCorrection :world-id="String(route.params.worldId)" :checkpoint-id="head.id" :state="store.state" @saved="corrected"/></Sheet></div></WorldAppearanceProvider></template>

